{"code": "from PIL import Image
import os

def check_images_in_dir(directory):
    """Check all images in a directory and return problematic files."""
    problematic_files = []

    if not os.path.exists(directory):
        print(f"Directory does not exist: {directory}")
        return problematic_files

    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        try:
            with Image.open(filepath) as img:
                img.verify()
        except Exception as e:
            problematic_files.append((filename, str(e)))

    return problematic_files

# Check all subdirectories
data_root = data_dir
dirs_to_check = ['Train/Normal', 'Train/Covid', 'Test/Normal', 'Test/Covid', 'Validation/Normal', 'Validation/Covid']

for d in dirs_to_check:
    full_path = os.path.join(data_root, d)
    print(f"\nChecking {d}:")
    problems = check_images_in_dir(full_path)
    if problems:
        print(f"  Found {len(problems)} problematic files:")
        for filename, error in problems:
            print(f"    - {filename}: {error}")
    else:
        print(f"  All files are valid!")"}

